-- Structural types/nullability from owner-supplied November 3 schema report.
-- Only serial ID defaults are modeled; other values are explicit in tests.
CREATE TABLE employees ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"name" text NOT NULL,"email" text,"phone" text,"color" text,"salary_rate" numeric,"is_active" boolean,"created_at" timestamp with time zone,"rotation_order" integer,"address" text,"notes" text,"street_address" text,"city" text,"state" text,"zip_code" text,"profile_image_url" text,"copy_communications_to_company" boolean,"first_name" text,"last_name" text,"is_admin" boolean,"password" text,"force_password_reset" boolean,"password_reset_token" text,"password_reset_expires" timestamp with time zone,"adp_worker_id" text,"hourly_rate" numeric,"is_tour_agent" boolean,"is_driver" boolean,"can_cancel_trip" boolean,"is_dispatcher" boolean);
CREATE TABLE clients ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"name" text NOT NULL,"email" text,"phone" text,"notes" text,"created_at" timestamp with time zone,"notification_preference" text,"address" text,"street_address" text,"city" text,"state" text,"zip_code" text,"is_active" boolean,"cc_emails" text,"is_new_passenger" boolean,"new_passenger_marked_at" timestamp with time zone,"referral_source" text);
CREATE TABLE services ("id" serial NOT NULL PRIMARY KEY,"tenant_id" integer,"name" text NOT NULL,"description" text,"default_price" numeric,"duration_minutes" integer,"is_variable_price" boolean,"display_order" integer,"is_active" boolean,"created_at" timestamp with time zone,"is_airport_service" boolean,"is_addon" boolean,"can_passenger_request" boolean,"is_tip_addon" boolean);
CREATE TABLE vehicles ("id" serial NOT NULL PRIMARY KEY,"employee_id" integer,"name" text NOT NULL,"year" text,"color" text,"plate" text,"is_active" boolean,"created_at" timestamp with time zone,"category" text,"passenger_capacity" integer);
CREATE TABLE vehicle_assignments ("id" serial NOT NULL PRIMARY KEY,"vehicle_id" integer NOT NULL,"employee_id" integer NOT NULL,"created_at" timestamp with time zone,"profile_image_url" text,"profile_description" text);
CREATE TABLE vehicle_categories ("id" serial NOT NULL PRIMARY KEY,"name" text NOT NULL,"display_order" integer,"is_active" boolean,"created_at" timestamp with time zone);
CREATE TABLE blocked_times ("id" serial NOT NULL PRIMARY KEY,"employee_id" integer,"start_time" timestamp with time zone NOT NULL,"end_time" timestamp with time zone NOT NULL,"reason" text,"is_deleted" boolean,"recurring_blocked_time_id" integer,"type" text);
ALTER TABLE vehicles ADD CONSTRAINT "vehicles_employee_id_fkey" FOREIGN KEY ("employee_id") REFERENCES employees(id);
ALTER TABLE vehicle_assignments ADD CONSTRAINT "vehicle_assignments_employee_id_fkey" FOREIGN KEY ("employee_id") REFERENCES employees(id);
ALTER TABLE vehicle_assignments ADD CONSTRAINT "vehicle_assignments_vehicle_id_fkey" FOREIGN KEY ("vehicle_id") REFERENCES vehicles(id);
ALTER TABLE blocked_times ADD CONSTRAINT "blocked_times_employee_id_fkey" FOREIGN KEY ("employee_id") REFERENCES employees(id);
